+        UIntValueT,
+        NUM_THREADS,
+        NUM_VALUES_PER_THREAD_FOR_SORT,
+        uint32_t,
+        4,
+        !(NUM_REGS_PER_THREAD <= 80 && NUM_VALUES_PER_THREAD_FOR_SORT >= 16)  // MemoizeOuterScan. Setting this to `false` can reduce register pressure. We use a simple heuristic here
