+    auto kernel = topk_kernel<Kernel>;
+    constexpr size_t smem_size = sizeof(typename Kernel::SharedMemoryPlanFP32);
+    KU_ASSERT(smem_size * Kernel::TARGET_OCCUPANCY <= args.shared_memory_size_per_sm);
