+float2 float2_mul(const float2 &a, const float2 &b) {
+    float2 c;
+    asm volatile(
+        "mul.f32x2 %0, %1, %2;\n"
+        : "=l"(reinterpret_cast<uint64_t&>(c))
+        : "l"(reinterpret_cast<uint64_t const&>(a)),
+          "l"(reinterpret_cast<uint64_t const&>(b)));
+    return c;
