+namespace kerutils {
+
+// Retrieve the value of `%smid` and check its range
+CUTE_DEVICE
+uint32_t get_sm_id_with_range_check(uint32_t num_physical_sms) {
+    uint32_t sm_id = get_sm_id();
+    if (!(sm_id < num_physical_sms)) {
+        trap();
+    }
+    return sm_id;
+}
+
+#ifndef KU_TRAP_ONLY_DEVICE_ASSERT
