+public:
+    template<typename... Args>
+    explicit KUException(const char *name, const char* file, const int line, Args&&... args) {
+        std::ostringstream oss;
+        
+        oss << name << " error (" << file << ":" << line << "): ";
+        (oss << ... << args);
+        message = oss.str();
+    }
+
