+    if (status_ != cudaSuccess) {                                                                             \
+        char _ku_buf[1024];                                                                                   \
+        snprintf(_ku_buf, sizeof(_ku_buf), "CUDA error (%s:%d): %s", __FILE__, __LINE__, cudaGetErrorString(status_)); \
+        fprintf(stderr, "%s\n", _ku_buf);                                                                    \
